function firstRedundantLink(stations, links) {
    const adjacent = Array.from({ length: stations }, () => []);
    for (const [a, b] of links) {
        const seen = new Set([a]);
        const stack = [a];
        while (stack.length > 0) {
            const station = stack.pop();
            for (const next of adjacent[station]) {
                if (!seen.has(next)) {
                    seen.add(next);
                    stack.push(next);
                }
            }
        }
        if (seen.has(b))
            return [a, b];
        adjacent[a].push(b);
        adjacent[b].push(a);
    }
    return [];
}

function firstRedundantLink(stations, links) {
    const parent = Array.from({ length: stations }, (_, i) => i);
    const find = (station) => {
        while (parent[station] !== station) {
            parent[station] = parent[parent[station]];
            station = parent[station];
        }
        return station;
    };
    for (const [a, b] of links) {
        const rootA = find(a);
        const rootB = find(b);
        if (rootA === rootB)
            return [a, b];
        parent[rootA] = rootB;
    }
    return [];
}
